import React, { useState, useEffect, useCallback } from 'react';
import {
  Card,
  Table,
  Tag,
  Badge,
  Progress,
  Statistic,
  Row,
  Col,
  Select,
  Input,
  Button,
  Modal,
  Descriptions,
  Space,
  Typography,
  message,
} from 'antd';
import {
  FileSearchOutlined,
  SafetyCertificateOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  EyeOutlined,
  SearchOutlined,
  StopOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { tradingMemoryApi } from '@/services/trading-memory';
import type {
  TradingMemory,
  TradingMemoryType,
  TradingMemoryStatus,
  TradingMemoryStatsResponse,
} from '@/services/types';
import styles from './index.module.scss';

const { Title } = Typography;

const TYPE_OPTIONS: { value: TradingMemoryType; label: string; color: string }[] = [
  { value: 'event_pattern', label: '事件模式', color: 'blue' },
  { value: 'signal_pattern', label: '信号模式', color: 'green' },
  { value: 'strategy_pattern', label: '策略模式', color: 'purple' },
  { value: 'market_regime_pattern', label: '市场环境模式', color: 'orange' },
  { value: 'risk_pattern', label: '风险模式', color: 'red' },
];

const STATUS_OPTIONS: { value: TradingMemoryStatus; label: string; color: string }[] = [
  { value: 'testing', label: '测试中', color: 'processing' },
  { value: 'active', label: '活跃', color: 'success' },
  { value: 'dormant', label: '休眠', color: 'warning' },
  { value: 'invalidated', label: '已失效', color: 'error' },
];

const getTypeLabel = (type: TradingMemoryType) =>
  TYPE_OPTIONS.find((o) => o.value === type) || { label: type, color: 'default' };

const getStatusOption = (status: TradingMemoryStatus) =>
  STATUS_OPTIONS.find((o) => o.value === status) || { label: status, color: 'default' };

const formatPercent = (val: number | undefined | null) => {
  if (val == null) return '-';
  return `${(val * 100).toFixed(2)}%`;
};

const formatDate = (dateStr: string | null | undefined) => {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleString('zh-CN');
};

const TradingMemoryPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<TradingMemory[]>([]);
  const [total, setTotal] = useState(0);
  const [current, setCurrent] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [stats, setStats] = useState<TradingMemoryStatsResponse | null>(null);

  const [filterType, setFilterType] = useState<TradingMemoryType | undefined>();
  const [filterStatus, setFilterStatus] = useState<TradingMemoryStatus | undefined>();
  const [keyword, setKeyword] = useState('');

  const [detailVisible, setDetailVisible] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailData, setDetailData] = useState<TradingMemory | null>(null);

  const fetchStats = useCallback(async () => {
    try {
      const res = await tradingMemoryApi.getStats();
      setStats(res);
    } catch {
      message.error('获取统计数据失败');
    }
  }, []);

  const fetchData = useCallback(
    async (page = current, size = pageSize) => {
      setLoading(true);
      try {
        const res = await tradingMemoryApi.getList({
          page,
          pageSize: size,
          type: filterType,
          status: filterStatus,
          keyword: keyword || undefined,
        });
        setData(res.data);
        setTotal(res.total);
        setCurrent(page);
        setPageSize(size);
      } catch {
        message.error('获取经验列表失败');
      } finally {
        setLoading(false);
      }
    },
    [current, pageSize, filterType, filterStatus, keyword],
  );

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  useEffect(() => {
    fetchData(1);
  }, [filterType, filterStatus]);

  const handleSearch = () => {
    fetchData(1);
  };

  const handleViewDetail = async (record: TradingMemory) => {
    setDetailVisible(true);
    setDetailLoading(true);
    try {
      const detail = await tradingMemoryApi.getById(record.id);
      setDetailData(detail);
    } catch {
      message.error('获取经验详情失败');
    } finally {
      setDetailLoading(false);
    }
  };

  const handleInvalidate = (record: TradingMemory) => {
    Modal.confirm({
      title: '确认操作',
      content: '确定要将此经验设为失效吗？',
      okText: '确定',
      cancelText: '取消',
      onOk: async () => {
        try {
          await tradingMemoryApi.invalidate(record.id);
          message.success('已设为失效');
          fetchData();
          fetchStats();
        } catch {
          message.error('操作失败');
        }
      },
    });
  };

  const columns: ColumnsType<TradingMemory> = [
    {
      title: '标题',
      dataIndex: 'title',
      key: 'title',
      width: 240,
      ellipsis: true,
    },
    {
      title: '类型',
      dataIndex: 'type',
      key: 'type',
      width: 120,
      render: (type: TradingMemoryType) => {
        const opt = getTypeLabel(type);
        return <Tag color={opt.color}>{opt.label}</Tag>;
      },
    },
    {
      title: '置信度',
      dataIndex: 'confidence',
      key: 'confidence',
      width: 120,
      render: (val: string) => {
        const num = parseFloat(val);
        const percent = Math.round(num * 100);
        const color = num >= 0.8 ? '#52c41a' : num >= 0.5 ? '#faad14' : '#ff4d4f';
        return <Progress percent={percent} size="small" strokeColor={color} />;
      },
    },
    {
      title: '胜率',
      key: 'winRate',
      width: 90,
      render: (_: unknown, record: TradingMemory) => formatPercent(record.stats?.winRate),
    },
    {
      title: '平均收益',
      key: 'avgReturn',
      width: 100,
      render: (_: unknown, record: TradingMemory) => {
        const val = record.stats?.avgReturn;
        if (val == null) return '-';
        const num = val * 100;
        return (
          <span style={{ color: num >= 0 ? '#52c41a' : '#ff4d4f' }}>
            {num >= 0 ? '+' : ''}{num.toFixed(2)}%
          </span>
        );
      },
    },
    {
      title: '样本量',
      key: 'sampleSize',
      width: 80,
      render: (_: unknown, record: TradingMemory) => record.stats?.sampleSize ?? '-',
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 90,
      render: (status: TradingMemoryStatus) => {
        const opt = getStatusOption(status);
        return <Badge status={opt.color as 'success'} text={opt.label} />;
      },
    },
    {
      title: '最近验证',
      dataIndex: 'lastValidatedAt',
      key: 'lastValidatedAt',
      width: 160,
      render: (val: string | null) => formatDate(val),
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      fixed: 'right',
      render: (_: unknown, record: TradingMemory) => (
        <Space>
          <Button type="link" icon={<EyeOutlined />} onClick={() => handleViewDetail(record)}>
            详情
          </Button>
          {record.status !== 'invalidated' && (
            <Button
              type="link"
              danger
              icon={<StopOutlined />}
              onClick={() => handleInvalidate(record)}
            >
              设为失效
            </Button>
          )}
        </Space>
      ),
    },
  ];

  return (
    <div className={styles.container}>
      <Title level={2}>交易经验</Title>

      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="总经验数"
              value={stats?.total ?? 0}
              valueStyle={{ color: '#1890ff' }}
              prefix={<FileSearchOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="高置信经验"
              value={stats?.highConfidence ?? 0}
              valueStyle={{ color: '#52c41a' }}
              prefix={<SafetyCertificateOutlined />}
            />
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              置信度 ≥ 0.8
            </Typography.Text>
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="有用经验"
              value={stats?.active ?? 0}
              valueStyle={{ color: '#722ed1' }}
              prefix={<CheckCircleOutlined />}
            />
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              状态为活跃
            </Typography.Text>
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="已失效经验"
              value={stats?.invalidated ?? 0}
              valueStyle={{ color: '#ff4d4f' }}
              prefix={<CloseCircleOutlined />}
            />
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              状态为已失效
            </Typography.Text>
          </Card>
        </Col>
      </Row>

      <Card style={{ marginBottom: 16 }}>
        <Space wrap>
          <Select
            placeholder="经验类型"
            allowClear
            style={{ width: 150 }}
            value={filterType}
            onChange={(val) => setFilterType(val)}
            options={TYPE_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
          />
          <Select
            placeholder="状态"
            allowClear
            style={{ width: 120 }}
            value={filterStatus}
            onChange={(val) => setFilterStatus(val)}
            options={STATUS_OPTIONS.map((o) => ({ value: o.value, label: o.label }))}
          />
          <Input.Search
            placeholder="搜索标题或摘要"
            allowClear
            style={{ width: 250 }}
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onSearch={handleSearch}
            enterButton={<SearchOutlined />}
          />
        </Space>
      </Card>

      <Card>
        <Table
          columns={columns}
          dataSource={data}
          rowKey="id"
          loading={loading}
          scroll={{ x: 1100 }}
          pagination={{
            current,
            pageSize,
            total,
            showSizeChanger: true,
            showTotal: (t) => `共 ${t} 条`,
          }}
          onChange={(pagination) => {
            fetchData(pagination.current || 1, pagination.pageSize || 20);
          }}
        />
      </Card>

      <Modal
        title={detailData?.title || '经验详情'}
        open={detailVisible}
        onCancel={() => {
          setDetailVisible(false);
          setDetailData(null);
        }}
        footer={null}
        width={720}
        loading={detailLoading}
      >
        {detailData && (
          <div className={styles.detailContent}>
            <Descriptions title="基本信息" bordered size="small" column={2}>
              <Descriptions.Item label="类型">
                <Tag color={getTypeLabel(detailData.type).color}>
                  {getTypeLabel(detailData.type).label}
                </Tag>
              </Descriptions.Item>
              <Descriptions.Item label="状态">
                <Badge
                  status={getStatusOption(detailData.status).color as 'success'}
                  text={getStatusOption(detailData.status).label}
                />
              </Descriptions.Item>
              <Descriptions.Item label="置信度">
                <Progress
                  percent={Math.round(parseFloat(detailData.confidence) * 100)}
                  size="small"
                  style={{ width: 120 }}
                />
              </Descriptions.Item>
              <Descriptions.Item label="标签">
                <Space wrap>
                  {detailData.tags?.map((tag) => (
                    <Tag key={tag}>{tag}</Tag>
                  ))}
                </Space>
              </Descriptions.Item>
              <Descriptions.Item label="摘要" span={2}>
                {detailData.summary}
              </Descriptions.Item>
              {detailData.rationale && (
                <Descriptions.Item label="依据说明" span={2}>
                  {detailData.rationale}
                </Descriptions.Item>
              )}
            </Descriptions>

            <Descriptions title="模式匹配" bordered size="small" column={2} style={{ marginTop: 16 }}>
              {detailData.pattern?.eventType && (
                <Descriptions.Item label="事件类型">{detailData.pattern.eventType}</Descriptions.Item>
              )}
              {detailData.pattern?.eventSubcategory && (
                <Descriptions.Item label="事件子类">{detailData.pattern.eventSubcategory}</Descriptions.Item>
              )}
              {detailData.pattern?.marketRegime && (
                <Descriptions.Item label="市场环境">{detailData.pattern.marketRegime}</Descriptions.Item>
              )}
              {detailData.pattern?.strategyId && (
                <Descriptions.Item label="策略ID">{detailData.pattern.strategyId}</Descriptions.Item>
              )}
              {detailData.pattern?.signalDirection && (
                <Descriptions.Item label="信号方向">
                  {detailData.pattern.signalDirection === 'long' ? '做多' : '做空'}
                </Descriptions.Item>
              )}
              {detailData.pattern?.scoreRange && (
                <Descriptions.Item label="分数范围">
                  [{detailData.pattern.scoreRange[0]}, {detailData.pattern.scoreRange[1]}]
                </Descriptions.Item>
              )}
            </Descriptions>

            <Descriptions title="统计数据" bordered size="small" column={2} style={{ marginTop: 16 }}>
              <Descriptions.Item label="样本量">{detailData.stats?.sampleSize ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="平均收益">{formatPercent(detailData.stats?.avgReturn)}</Descriptions.Item>
              <Descriptions.Item label="期望值">{formatPercent(detailData.stats?.expectancy)}</Descriptions.Item>
              <Descriptions.Item label="胜率">{formatPercent(detailData.stats?.winRate)}</Descriptions.Item>
              <Descriptions.Item label="夏普比率">{detailData.stats?.sharpeRatio?.toFixed(2) ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="最大回撤">{formatPercent(detailData.stats?.maxDrawdown)}</Descriptions.Item>
              <Descriptions.Item label="平均持有天数">{detailData.stats?.avgHoldDays ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="盈亏因子">{detailData.stats?.profitFactor?.toFixed(2) ?? '-'}</Descriptions.Item>
              <Descriptions.Item label="PnL标准差">{detailData.stats?.pnlStdDev?.toFixed(4) ?? '-'}</Descriptions.Item>
            </Descriptions>

            <Descriptions title="时间信息" bordered size="small" column={2} style={{ marginTop: 16 }}>
              <Descriptions.Item label="首次观察">{formatDate(detailData.firstObservedAt)}</Descriptions.Item>
              <Descriptions.Item label="最近验证">{formatDate(detailData.lastValidatedAt)}</Descriptions.Item>
              <Descriptions.Item label="失效时间">{formatDate(detailData.invalidatedAt)}</Descriptions.Item>
              <Descriptions.Item label="最近计算">{formatDate(detailData.lastComputedAt)}</Descriptions.Item>
            </Descriptions>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default TradingMemoryPage;

23.__content:
import React, { useState, useEffect, useCallback } from 'react';
import {
  Card,
  Table,
  Tag,
  Progress,
  Statistic,
  Row,
  Col,
  Select,
  Button,
  Modal,
  Descriptions,
  Space,
  Typography,
  message,
} from 'antd';
import {
  ThunderboltOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  EyeOutlined,
  ExclamationCircleOutlined,
  SafetyCertificateOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { tradingAgentApi } from '@/services/trading-agent';
import type {
  TradingAgentDecision,
  TradingAgentStats,
} from '@/services/types';
import styles from './index.module.scss';

const { Title } = Typography;

const DECISION_TYPE_MAP: Record<string, { label: string; color: string }> = {
  execute: { label: '执行', color: 'green' },
  reject: { label: '拒绝', color: 'orange' },
  adjust_position: { label: '调仓', color: 'blue' },
  close_position: { label: '平仓', color: 'red' },
  modify_holding: { label: '改仓', color: 'purple' },
};

const DECISION_MAP: Record<string, { label: string; color: string }> = {
  approved: { label: '通过', color: 'green' },
  rejected: { label: '拒绝', color: 'red' },
};

const RISK_LEVEL_MAP: Record<string, { label: string; color: string }> = {
  low: { label: '低', color: 'green' },
  medium: { label: '中', color: 'orange' },
  high: { label: '高', color: 'red' },
  critical: { label: '严重', color: 'magenta' },
};

const DECISION_FILTER_OPTIONS = [
  { value: 'approved', label: '通过' },
  { value: 'rejected', label: '拒绝' },
];

const RISK_LEVEL_FILTER_OPTIONS = [
  { value: 'low', label: '低' },
  { value: 'medium', label: '中' },
  { value: 'high', label: '高' },
  { value: 'critical', label: '严重' },
];

const formatDate = (dateStr: string | null | undefined) => {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleString('zh-CN');
};

const truncateId = (id: string) => {
  if (id.length <= 12) return id;
  return `${id.slice(0, 8)}...`;
};

const TradingAgentPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<TradingAgentDecision[]>([]);
  const [total, setTotal] = useState(0);
  const [current, setCurrent] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [stats, setStats] = useState<TradingAgentStats | null>(null);

  const [filterDecision, setFilterDecision] = useState<'approved' | 'rejected' | undefined>();
  const [filterRiskLevel, setFilterRiskLevel] = useState<'low' | 'medium' | 'high' | 'critical' | undefined>();

  const [detailVisible, setDetailVisible] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailData, setDetailData] = useState<TradingAgentDecision | null>(null);

  const fetchStats = useCallback(async () => {
    try {
      const res = await tradingAgentApi.getStats();
      setStats(res);
    } catch {
      message.error('获取统计数据失败');
    }
  }, []);

  const fetchData = useCallback(
    async (page = current, size = pageSize) => {
      setLoading(true);
      try {
        const res = await tradingAgentApi.getDecisions({
          page,
          pageSize: size,
          decision: filterDecision,
          riskLevel: filterRiskLevel,
        });
        setData(res.data);
        setTotal(res.total);
        setCurrent(page);
        setPageSize(size);
      } catch {
        message.error('获取决策列表失败');
      } finally {
        setLoading(false);
      }
    },
    [current, pageSize, filterDecision, filterRiskLevel],
  );

  useEffect(() => {
    fetchStats();
  }, [fetchStats]);

  useEffect(() => {
    fetchData(1);
  }, [filterDecision, filterRiskLevel]);

  const handleViewDetail = async (record: TradingAgentDecision) => {
    setDetailVisible(true);
    setDetailLoading(true);
    try {
      const detail = await tradingAgentApi.getDecisionById(record.id);
      setDetailData(detail);
    } catch {
      message.error('获取决策详情失败');
    } finally {
      setDetailLoading(false);
    }
  };

  const columns: ColumnsType<TradingAgentDecision> = [
    {
      title: '时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 170,
      render: (val: string) => formatDate(val),
    },
    {
      title: '信号ID',
      dataIndex: 'signalId',
      key: 'signalId',
      width: 120,
      render: (val: string) => truncateId(val),
    },
    {
      title: '决策类型',
      dataIndex: 'decisionType',
      key: 'decisionType',
      width: 100,
      render: (val: string) => {
        const opt = DECISION_TYPE_MAP[val] || { label: val, color: 'default' };
        return <Tag color={opt.color}>{opt.label}</Tag>;
      },
    },
    {
      title: '决策结果',
      dataIndex: 'decision',
      key: 'decision',
      width: 90,
      render: (val: string) => {
        const opt = DECISION_MAP[val] || { label: val, color: 'default' };
        return <Tag color={opt.color}>{opt.label}</Tag>;
      },
    },
    {
      title: '风险等级',
      dataIndex: 'riskLevel',
      key: 'riskLevel',
      width: 90,
      render: (val: string) => {
        const opt = RISK_LEVEL_MAP[val] || { label: val, color: 'default' };
        return <Tag color={opt.color}>{opt.label}</Tag>;
      },
    },
    {
      title: '置信度',
      dataIndex: 'confidence',
      key: 'confidence',
      width: 140,
      render: (val: number) => {
        const percent = Math.round(val * 100);
        const color = val >= 0.8 ? '#52c41a' : val >= 0.5 ? '#faad14' : '#ff4d4f';
        return (
          <Space>
            <span>{percent}%</span>
            <Progress percent={percent} size="small" strokeColor={color} style={{ width: 80 }} />
          </Space>
        );
      },
    },
    {
      title: '沉淀经验',
      dataIndex: 'memoryCreated',
      key: 'memoryCreated',
      width: 90,
      render: (val: boolean) =>
        val ? (
          <CheckCircleOutlined style={{ color: '#52c41a', fontSize: 16 }} />
        ) : (
          <CloseCircleOutlined style={{ color: '#d9d9d9', fontSize: 16 }} />
        ),
    },
    {
      title: '操作',
      key: 'action',
      width: 80,
      fixed: 'right',
      render: (_: unknown, record: TradingAgentDecision) => (
        <Button type="link" icon={<EyeOutlined />} onClick={() => handleViewDetail(record)}>
          详情
        </Button>
      ),
    },
  ];

  const renderContextSnapshot = (snapshot: TradingAgentDecision['contextSnapshot']) => {
    if (!snapshot) return '-';
    return (
      <div className={styles.detailContent}>
        {snapshot.accountInfo && Object.keys(snapshot.accountInfo).length > 0 && (
          <Descriptions title="账户信息" bordered size="small" column={1} style={{ marginTop: 16 }}>
            {Object.entries(snapshot.accountInfo).map(([key, value]) => (
              <Descriptions.Item key={key} label={key}>
                {typeof value === 'object' ? JSON.stringify(value) : String(value)}
              </Descriptions.Item>
            ))}
          </Descriptions>
        )}
        {snapshot.signalInfo && Object.keys(snapshot.signalInfo).length > 0 && (
          <Descriptions title="信号信息" bordered size="small" column={1} style={{ marginTop: 16 }}>
            {Object.entries(snapshot.signalInfo).map(([key, value]) => (
              <Descriptions.Item key={key} label={key}>
                {typeof value === 'object' ? JSON.stringify(value) : String(value)}
              </Descriptions.Item>
            ))}
          </Descriptions>
        )}
        {snapshot.relevantMemories && snapshot.relevantMemories.length > 0 && (
          <Descriptions title="相关经验" bordered size="small" column={1} style={{ marginTop: 16 }}>
            <Descriptions.Item label="经验数量">{snapshot.relevantMemories.length}</Descriptions.Item>
            {snapshot.relevantMemories.map((mem, idx) => (
              <Descriptions.Item key={idx} label={`经验 ${idx + 1}`}>
                {JSON.stringify(mem)}
              </Descriptions.Item>
            ))}
          </Descriptions>
        )}
        {snapshot.currentPositions && snapshot.currentPositions.length > 0 && (
          <Descriptions title="当前持仓" bordered size="small" column={1} style={{ marginTop: 16 }}>
            <Descriptions.Item label="持仓数量">{snapshot.currentPositions.length}</Descriptions.Item>
            {snapshot.currentPositions.map((pos, idx) => (
              <Descriptions.Item key={idx} label={`持仓 ${idx + 1}`}>
                {JSON.stringify(pos)}
              </Descriptions.Item>
            ))}
          </Descriptions>
        )}
      </div>
    );
  };

  return (
    <div className={styles.container}>
      <Title level={2}>交易 Agent</Title>

      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="今日决策数"
              value={stats?.totalToday ?? 0}
              valueStyle={{ color: '#1890ff' }}
              prefix={<ThunderboltOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="执行数"
              value={stats?.approvedToday ?? 0}
              valueStyle={{ color: '#52c41a' }}
              prefix={<CheckCircleOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="拒绝数"
              value={stats?.rejectedToday ?? 0}
              valueStyle={{ color: '#faad14' }}
              prefix={<ExclamationCircleOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="高风险拒绝"
              value={stats?.highRiskRejectedToday ?? 0}
              valueStyle={{ color: '#ff4d4f' }}
              prefix={<SafetyCertificateOutlined />}
            />
          </Card>
        </Col>
      </Row>

      <Card style={{ marginBottom: 16 }}>
        <Space wrap>
          <Select
            placeholder="决策结果"
            allowClear
            style={{ width: 150 }}
            value={filterDecision}
            onChange={(val) => setFilterDecision(val)}
            options={DECISION_FILTER_OPTIONS}
          />
          <Select
            placeholder="风险等级"
            allowClear
            style={{ width: 150 }}
            value={filterRiskLevel}
            onChange={(val) => setFilterRiskLevel(val)}
            options={RISK_LEVEL_FILTER_OPTIONS}
          />
        </Space>
      </Card>

      <Card>
        <Table
          columns={columns}
          dataSource={data}
          rowKey="id"
          loading={loading}
          scroll={{ x: 980 }}
          pagination={{
            current,
            pageSize,
            total,
            showSizeChanger: true,
            showTotal: (t) => `共 ${t} 条`,
          }}
          onChange={(pagination) => {
            fetchData(pagination.current || 1, pagination.pageSize || 20);
          }}
        />
      </Card>

      <Modal
        title="决策详情"
        open={detailVisible}
        onCancel={() => {
          setDetailVisible(false);
          setDetailData(null);
        }}
        footer={null}
        width={720}
        loading={detailLoading}
      >
        {detailData && (
          <div className={styles.detailContent}>
            <Descriptions title="基本信息" bordered size="small" column={2}>
              <Descriptions.Item label="决策类型">
                <Tag color={(DECISION_TYPE_MAP[detailData.decisionType] || {}).color || 'default'}>
                  {(DECISION_TYPE_MAP[detailData.decisionType] || {}).label || detailData.decisionType}
                </Tag>
              </Descriptions.Item>
              <Descriptions.Item label="决策结果">
                <Tag color={(DECISION_MAP[detailData.decision] || {}).color || 'default'}>
                  {(DECISION_MAP[detailData.decision] || {}).label || detailData.decision}
                </Tag>
              </Descriptions.Item>
              <Descriptions.Item label="置信度">
                <Progress
                  percent={Math.round(detailData.confidence * 100)}
                  size="small"
                  style={{ width: 120 }}
                />
              </Descriptions.Item>
              <Descriptions.Item label="风险等级">
                <Tag color={(RISK_LEVEL_MAP[detailData.riskLevel] || {}).color || 'default'}>
                  {(RISK_LEVEL_MAP[detailData.riskLevel] || {}).label || detailData.riskLevel}
                </Tag>
              </Descriptions.Item>
            </Descriptions>

            <Descriptions title="推理过程" bordered size="small" column={1} style={{ marginTop: 16 }}>
              <Descriptions.Item label="推理说明">{detailData.rationale}</Descriptions.Item>
            </Descriptions>

            {detailData.positionAction && (
              <Descriptions title="交易动作" bordered size="small" column={2} style={{ marginTop: 16 }}>
                <Descriptions.Item label="动作">
                  <Tag color={detailData.positionAction.action === 'buy' ? 'green' : 'red'}>
                    {detailData.positionAction.action === 'buy' ? '买入' : '卖出'}
                  </Tag>
                </Descriptions.Item>
                <Descriptions.Item label="股票">{detailData.positionAction.stockName} ({detailData.positionAction.stockCode})</Descriptions.Item>
                <Descriptions.Item label="数量">{detailData.positionAction.quantity}</Descriptions.Item>
                <Descriptions.Item label="价格">{detailData.positionAction.price ?? '-'}</Descriptions.Item>
                <Descriptions.Item label="止盈价">{detailData.positionAction.takeProfitPrice ?? '-'}</Descriptions.Item>
                <Descriptions.Item label="止损价">{detailData.positionAction.stopLossPrice ?? '-'}</Descriptions.Item>
              </Descriptions>
            )}

            {detailData.contextSnapshot && renderContextSnapshot(detailData.contextSnapshot)}

            <Descriptions title="沉淀经验" bordered size="small" column={1} style={{ marginTop: 16 }}>
              <Descriptions.Item label="是否沉淀">
                {detailData.memoryCreated ? (
                  <CheckCircleOutlined style={{ color: '#52c41a' }} />
                ) : (
                  <CloseCircleOutlined style={{ color: '#d9d9d9' }} />
                )}
              </Descriptions.Item>
            </Descriptions>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default TradingAgentPage;

24.__content:
import React, { useState, useEffect, useCallback } from 'react';
import {
  Card,
  Table,
  Tag,
  Statistic,
  Row,
  Col,
  Select,
  Button,
  Input,
  Space,
  Typography,
  message,
  Modal,
} from 'antd';
import {
  FilterOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  SaveOutlined,
  UndoOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { useNavigate } from 'umi';
import { newsFilterAgentApi } from '@/services/news-filter-agent';
import type {
  NewsFilterAgentLog,
  NewsFilterAgentStats,
} from '@/services/news-filter-agent';

const { Title } = Typography;
const { TextArea } = Input;

const DEFAULT_PROMPT = `你是一个金融新闻过滤器。你的任务是根据新闻标题判断这条新闻是否值得进行深度金融事件分析。

判断标准：
1. 新闻是否与金融市场、股票、经济政策相关
2. 新闻是否可能包含影响交易决策的信息
3. 新闻是否涉及上市公司、行业政策、宏观经济等

应该跳过（skip）的新闻类型：
- 纯娱乐、体育新闻
- 与金融市场无关的社会新闻
- 重复或无实质内容的新闻
- 广告或推广内容

应该通过（analyze）的新闻类型：
- 上市公司相关新闻（业绩、并购、重组等）
- 宏观经济政策新闻（利率、GDP、通胀等）
- 行业政策变化新闻
- 市场行情相关新闻
- 国际贸易、地缘政治对市场有影响的新闻

请根据新闻标题做出判断，返回 JSON 格式结果。

新闻标题：{newsTitle}`;

const DECISION_MAP: Record<string, { label: string; color: string }> = {
  analyze: { label: '通过', color: 'green' },
  skip: { label: '跳过', color: 'orange' },
};

const DECISION_FILTER_OPTIONS = [
  { value: 'analyze', label: '通过' },
  { value: 'skip', label: '跳过' },
];

const formatDate = (dateStr: string | null | undefined) => {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleString('zh-CN');
};

const NewsFilterAgentPage: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<NewsFilterAgentLog[]>([]);
  const [total, setTotal] = useState(0);
  const [current, setCurrent] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [stats, setStats] = useState<NewsFilterAgentStats | null>(null);
  const [filterDecision, setFilterDecision] = useState<string | undefined>();
  const [prompt, setPrompt] = useState(DEFAULT_PROMPT);
  const [promptSaving, setPromptSaving] = useState(false);

  const fetchStats = useCallback(async () => {
    try {
      const res = await newsFilterAgentApi.getStats();
      setStats(res);
    } catch {
      message.error('获取统计数据失败');
    }
  }, []);

  const fetchConfig = useCallback(async () => {
    try {
      const config = await newsFilterAgentApi.getConfig();
      if (config.prompt) {
        setPrompt(config.prompt);
      }
    } catch {
      message.error('获取配置失败');
    }
  }, []);

  const fetchData = useCallback(
    async (page = current, size = pageSize) => {
      setLoading(true);
      try {
        const res = await newsFilterAgentApi.getLogs({
          page,
          pageSize: size,
          decision: filterDecision,
        });
        setData(res.data);
        setTotal(res.total);
        setCurrent(page);
        setPageSize(size);
      } catch {
        message.error('获取日志列表失败');
      } finally {
        setLoading(false);
      }
    },
    [current, pageSize, filterDecision],
  );

  useEffect(() => {
    fetchStats();
    fetchConfig();
  }, [fetchStats, fetchConfig]);

  useEffect(() => {
    fetchData(1);
  }, [filterDecision]);

  const handleSavePrompt = async () => {
    if (!prompt.includes('{newsTitle}')) {
      message.error('Prompt 必须包含 {newsTitle} 占位符');
      return;
    }
    setPromptSaving(true);
    try {
      await newsFilterAgentApi.updateConfig({ prompt });
      message.success('Prompt 保存成功');
    } catch {
      message.error('保存 Prompt 失败');
    } finally {
      setPromptSaving(false);
    }
  };

  const handleResetPrompt = () => {
    Modal.confirm({
      title: '确定要恢复默认 Prompt 吗？',
      onOk: async () => {
        setPrompt(DEFAULT_PROMPT);
        try {
          await newsFilterAgentApi.updateConfig({ prompt: DEFAULT_PROMPT });
          message.success('已恢复默认 Prompt');
        } catch {
          message.error('恢复默认 Prompt 失败');
        }
      },
    });
  };

  const columns: ColumnsType<NewsFilterAgentLog> = [
    {
      title: '时间',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 170,
      render: (val: string) => formatDate(val),
    },
    {
      title: '新闻标题',
      dataIndex: 'newsTitle',
      key: 'newsTitle',
      width: 300,
      render: (title: string, record: NewsFilterAgentLog) =>
        title ? (
          <a onClick={() => record.newsId && navigate(`/news/${record.newsId}`)}>{title.length > 40 ? title.slice(0, 40) + '...' : title}</a>
        ) : '-',
    },
    {
      title: '判断结果',
      dataIndex: 'decision',
      key: 'decision',
      width: 100,
      render: (val: string) => {
        const opt = DECISION_MAP[val] || { label: val, color: 'default' };
        return <Tag color={opt.color}>{opt.label}</Tag>;
      },
    },
    {
      title: '置信度',
      dataIndex: 'confidence',
      key: 'confidence',
      width: 100,
      render: (val: string | null) => {
        if (val === null || val === undefined) return '-';
        const percent = Math.round(Number(val) * 100);
        return `${percent}%`;
      },
    },
    {
      title: '推理理由',
      dataIndex: 'reasoning',
      key: 'reasoning',
      ellipsis: true,
      render: (val: string | null) => val || '-',
    },
  ];

  return (
    <div>
      <Title level={2}>新闻过滤 Agent</Title>

      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="今日过滤总数"
              value={stats?.total ?? 0}
              valueStyle={{ color: '#1890ff' }}
              prefix={<FilterOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="通过数"
              value={stats?.analyzed ?? 0}
              valueStyle={{ color: '#52c41a' }}
              prefix={<CheckCircleOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="跳过数"
              value={stats?.skipped ?? 0}
              valueStyle={{ color: '#faad14' }}
              prefix={<CloseCircleOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="跳过率"
              value={stats?.skipRate ?? 0}
              suffix="%"
              valueStyle={{ color: '#722ed1' }}
              prefix={<FilterOutlined />}
            />
          </Card>
        </Col>
      </Row>

      <Card title="过滤 Prompt" style={{ marginBottom: 16 }}>
        <TextArea
          rows={8}
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          style={{ marginBottom: 12 }}
        />
        <Space>
          <Button
            type="primary"
            icon={<SaveOutlined />}
            onClick={handleSavePrompt}
            loading={promptSaving}
          >
            保存
          </Button>
          <Button
            icon={<UndoOutlined />}
            onClick={handleResetPrompt}
          >
            恢复默认
          </Button>
        </Space>
      </Card>

      <Card style={{ marginBottom: 16 }}>
        <Space wrap>
          <Select
            placeholder="判断结果"
            allowClear
            style={{ width: 150 }}
            value={filterDecision}
            onChange={(val) => setFilterDecision(val)}
            options={DECISION_FILTER_OPTIONS}
          />
        </Space>
      </Card>

      <Card>
        <Table
          columns={columns}
          dataSource={data}
          rowKey="id"
          loading={loading}
          scroll={{ x: 800 }}
          pagination={{
            current,
            pageSize,
            total,
            showSizeChanger: true,
            showTotal: (t) => `共 ${t} 条`,
          }}
          onChange={(pagination) => {
            fetchData(pagination.current || 1, pagination.pageSize || 20);
          }}
        />
      </Card>
    </div>
  );
};

export default NewsFilterAgentPage;

