          loading={loading}
          pagination={false}
          size="small"
        />
      </Card>

      <Card title="说明" style={{ marginTop: 16 }}>
        <Space direction="vertical">
          <Text>
            <ClockCircleOutlined style={{ marginRight: 8, color: '#1890ff' }} />
            <strong>Cron 表达式：</strong>用于定义任务的执行时间规则
          </Text>
          <Text>
            <CheckCircleOutlined style={{ marginRight: 8, color: '#52c41a' }} />
