          user: '用户',
          api_key: 'API Key',
          strategy: '策略',
          webhook: 'Webhook',
          simulation_account: '模拟账户',
          simulation_trade: '模拟交易',
          signal_rule: '信号规则',
          blacklist: '黑名单',
          scheduler_task: '定时任务',
        };
        return <Tag color={colorMap[resource] || 'default'}>{labelMap[resource] || resource}</Tag>;
